import 'dart:async';

import 'package:audioplayers/audioplayers.dart';

import 'audio_taper.dart';

/// Short procedural sound effects (assets/audio, generated by
/// tool/generate_sounds.py). All playback is fire-and-forget and gated by
/// the user's "Sound effects" setting.
class SoundService {
  SoundService({required this.isEnabled});

  final bool Function() isEnabled;

  /// A small pool so rapid keyboard taps don't cut each other off. Taps are
  /// the only latency-critical sound (one per keystroke), so they stay on the
  /// low-latency SoundPool path.
  final List<AudioPlayer> _tapPool = [];
  int _tapIndex = 0;

  /// The discrete event sounds (hint, conflict, word, success, achievement).
  /// Each gets a SMALL ROUND-ROBIN POOL of media players. A quick retrigger
  /// (several conflicts in a row, a burst of completed words) plays a fresh,
  /// already-finished voice while the previous one rings out naturally —
  /// instead of seek-cutting a still-ringing tail straight to silence, the
  /// discontinuity that crackled on the old single-player-per-sound path.
  final Map<String, List<AudioPlayer>> _players = {};

  /// Round-robin cursor per discrete sound, so successive plays alternate
  /// voices (giving each the most time to decay before it is reused).
  final Map<String, int> _voiceIndex = {};
  bool _ready = false;

  /// Every discrete voice across all pools — for volume changes and teardown.
  Iterable<AudioPlayer> get _eventVoices => _players.values.expand((v) => v);

  /// 0..1 user multiplier (soundVolume from settings). The WAVs are already
  /// balanced against each other; this scales the whole family uniformly.
  double _volume = 1.0;

  /// Applies the user's effect-volume preference to every pooled and discrete
  /// player. Cheap and idempotent, so Settings can call it on every change.
  void setUserVolume(double value) {
    // Perceptual taper: loudness is roughly logarithmic, so a linear slider made
    // the lower half feel nearly as loud as the top. Squaring the position gives
    // a natural audio taper where the on-screen % tracks how loud it actually
    // sounds; silence and full stay exact (0 -> 0, 1 -> 1).
    _volume = audioTaper(value);
    if (!_ready) return;
    for (final p in [..._tapPool, ..._eventVoices]) {
      unawaited(p.setVolume(_volume).catchError((_) {}));
    }
  }

  Future<void> initialize() async {
    // Idempotent: a repeat call after a successful init must not stack a second
    // tap pool / set of discrete players. After a FAILED init (_ready stays
    // false) a retry is allowed, so first tear down anything a prior attempt
    // left behind.
    if (_ready) return;
    for (final p in [..._tapPool, ..._eventVoices]) {
      try {
        await p.dispose();
      } catch (_) {}
    }
    _tapPool.clear();
    _players.clear();
    _voiceIndex.clear();
    try {
      // Game/media stream, never the ringtone stream: volume keys must
      // control MEDIA volume. (The old AudioContextConfig(respectSilence:
      // true) forced AndroidUsageType.notificationRingtone, which made all
      // audio behave like a call/ringtone and follow the RING volume.)
      // audioFocus none = blips and the music bed never pause or duck the
      // user's own podcast/music.
      await AudioPlayer.global.setAudioContext(
        AudioContext(
          android: const AudioContextAndroid(
            usageType: AndroidUsageType.game,
            contentType: AndroidContentType.music,
            audioFocus: AndroidAudioFocus.none,
            audioMode: AndroidAudioMode.normal,
          ),
          // ambient already implies mixing with other audio; passing
          // mixWithOthers explicitly trips the package assert (it is only
          // allowed for playback/playAndRecord/multiRoute).
          iOS: AudioContextIOS(
            category: AVAudioSessionCategory.ambient,
            options: const {},
          ),
        ),
      );
      // A roomier pool (5): at fast typing speeds each voice has finished long
      // before it is reused, so a retrigger never has to stop a still-ringing
      // tap — which is what clicked on the old 3-voice pool.
      for (var i = 0; i < 5; i++) {
        _tapPool.add(await _load('tap.wav', lowLatency: true));
      }
      // The long fanfares (success ~2s, achievement) can still be ringing when
      // they are asked to play again, so they get a THIRD voice: the round-robin
      // then always lands on a finished voice and seek-to-zero never has to cut
      // a live tail into a click. The short cues are fine with two.
      const longVoices = {'success.wav', 'achievement.wav'};
      for (final name in [
        'hint.wav',
        'conflict.wav',
        'success.wav',
        'achievement.wav',
        'word.wav',
      ]) {
        final voices = longVoices.contains(name) ? 3 : 2;
        _players[name] = [
          for (var i = 0; i < voices; i++) await _load(name, lowLatency: false),
        ];
      }
      _ready = true;
    } catch (_) {
      // Audio is never worth crashing over (emulators without audio,
      // restricted web contexts...): stay silent instead.
      _ready = false;
    }
  }

  Future<AudioPlayer> _load(String asset, {required bool lowLatency}) async {
    final p = AudioPlayer();
    await p.setPlayerMode(
      lowLatency ? PlayerMode.lowLatency : PlayerMode.mediaPlayer,
    );
    await p.setSource(AssetSource('audio/$asset'));
    await p.setReleaseMode(ReleaseMode.stop);
    return p;
  }

  /// Last play time per discrete sound, for the spam guard below.
  final Map<String, int> _lastPlayedMs = {};

  /// Minimum gap before the SAME discrete sound may retrigger. Rapid repeats
  /// (e.g. several words completing in a burst) would otherwise seek-restart
  /// the clip mid-attack and click; dropping the extra retrigger keeps the
  /// first play clean. Distinct sounds are unaffected (per-key).
  static const int _minGapMs = 70;

  /// Replay a media-player sound from its start without a stop()/teardown.
  /// seek-to-zero repositions in place (no SoundPool stream rebuild), so the
  /// ringing tail of the previous play is never hard-cut into a click.
  void _play(String key) {
    final pool = _players[key];
    if (!_ready || pool == null || pool.isEmpty || !isEnabled()) return;
    final now = DateTime.now().millisecondsSinceEpoch;
    final last = _lastPlayedMs[key];
    if (last != null && now - last < _minGapMs) return;
    _lastPlayedMs[key] = now;
    // Advance to the NEXT voice so the previous play keeps ringing out on its
    // own voice. The voice we pick has already finished (ReleaseMode.stop), so
    // seek-to-zero + resume restarts it cleanly from silence — no tail to cut,
    // no click.
    final idx = _voiceIndex[key] ?? 0;
    _voiceIndex[key] = (idx + 1) % pool.length;
    final player = pool[idx];
    unawaited(
      player
          .seek(Duration.zero)
          .then((_) => player.resume())
          .catchError((_) {}),
    );
  }

  void tap() {
    if (!_ready || _tapPool.isEmpty || !isEnabled()) return;
    _tapIndex = (_tapIndex + 1) % _tapPool.length;
    // Low-latency (SoundPool) does not support seek; a stop()+resume on a
    // pooled, already-finished player retriggers it without an audible cut.
    final player = _tapPool[_tapIndex];
    unawaited(player.stop().then((_) => player.resume()).catchError((_) {}));
  }

  void hint() => _play('hint.wav');

  void conflict() => _play('conflict.wav');

  /// A single soft bell when a typed guess finishes a whole word.
  void wordComplete() => _play('word.wav');

  void success() => _play('success.wav');

  void achievement() => _play('achievement.wav');

  void dispose() {
    for (final p in [..._tapPool, ..._eventVoices]) {
      p.dispose();
    }
  }
}
